{
    using System.Text;
    using Fanex.BetList.Core.Templates;
    using NUnit.Framework;

    public class WrapperTemplate_Handicap_Block : Template_Handicap_Block
    {
        public void SetAssigned(bool isAssigned)
        {
            this.IsAssigned = isAssigned;
